// `.entire/`. Cloud environment install commands should invoke it.
const InstallCLIScriptName = "install-cli.sh"

// InstallCLIMarker is the repo-relative path of the helper. It is the identity
// of an Entire install step: detection and removal both key on it, so the
// wording of InstallCLIStep can change without stranding steps written by an
// older CLI in a committed environment file.
const InstallCLIMarker = paths.EntireDir + "/" + InstallCLIScriptName

// InstallCLIStep is the install-command fragment that runs the helper.
//
// Two properties are load-bearing, and both exist because a broken step does
// not merely skip Entire — it fails the host's whole install command:
//
//   - It resolves the helper from the repository root rather than the current
//     directory. Install commands are chained with `&&`, so any earlier `cd`
//     (`cd frontend && npm ci && …`, routine in a monorepo) carries over.
//   - It tolerates a missing helper. The step and `.entire/install-cli.sh`
//     must both be committed for Cloud Agents to see them; a user who commits
//     the environment file and not the (newly untracked) helper would
//     otherwise get an environment that no longer builds.
const InstallCLIStep = `bash "$(git rev-parse --show-toplevel)/` + InstallCLIMarker + `" || true`

const maxScriptScanBytes = 1 << 20

