// AppendInstallStep adds step to the end of install. Empty install becomes
// step alone.
//
// A trailing chain operator (`&&`, `;`) is dropped so the join does not
// produce `a && && b`. A trailing single `&` is left alone: it is the
// background operator, and both eating it (turning a backgrounded command
// into a blocking one) and joining onto it with `&&` (a shell syntax error)
// would silently break the host's install command.
func AppendInstallStep(install, step string) string {
	install = strings.TrimSpace(install)
	for {
		trimmed := strings.TrimRight(install, " \t")
		if cut, ok := strings.CutSuffix(trimmed, "&&"); ok {
			install = cut
			continue
		}
		if cut, ok := strings.CutSuffix(trimmed, ";"); ok {
			install = cut
			continue
		}
		install = trimmed
		break
	}
	if install == "" {
		return step
	}
	if strings.HasSuffix(install, "&") {
		// `cmd & step` is the only valid join after a background operator.
		return install + " " + step
	}
	return install + " && " + step
}

// StripInstallStep removes the command that runs the Entire install helper,
// wherever it sits in the chain, along with the operator that joined it.
//
// Matching is on InstallCLIMarker rather than on the exact InstallCLIStep
// text, so a step written by an older CLI (or moved by hand) is still removed
// — MentionsEntireInstall already recognizes those, and a detect/remove pair
// that disagree would leave `entire disable` stranding wiring it can see.
// Bytes outside the removed span are preserved exactly.
func StripInstallStep(install string) string {
	for {
		marker := strings.Index(install, InstallCLIMarker)
		if marker < 0 {
			return strings.TrimSpace(install)
		}
		cmdStart, sepStart := commandStart(install, marker)
		cmdEnd, sepEnd := commandEnd(install, marker+len(InstallCLIMarker))
		switch {
		case cmdStart > 0:
			// Joined to something on its left: take the operator with it.
			install = install[:sepStart] + install[cmdEnd:]
		case sepEnd > cmdEnd:
			// First in the chain: take the operator on its right instead.
			install = install[sepEnd:]
		default:
			return ""
		}
	}
}

// commandStart returns the offset of the command containing pos and the offset
// of the shell operator that precedes it (both 0 when pos is in the first
// command of the chain).
func commandStart(s string, pos int) (cmdStart, sepStart int) {
	for i := pos - 1; i >= 0; i-- {
		switch {
		case s[i] == ';':
			return i + 1, i
		case s[i] == '&' && i > 0 && s[i-1] == '&':
			return i + 1, i - 1
		case s[i] == '&':
			return i + 1, i
		case s[i] == '|' && i > 0 && s[i-1] == '|':
			return i + 1, i - 1
		}
	}
	return 0, 0
}

// commandEnd returns the offset just past the command containing pos and the
// offset just past the operator that follows it (equal when the command ends
// the chain). A lone `|` is a pipeline, not a chain operator, so it does not
// end the command.
func commandEnd(s string, pos int) (cmdEnd, sepEnd int) {
	for i := pos; i < len(s); i++ {
		switch {
		case s[i] == ';':
			return i, i + 1
		case s[i] == '&' && i+1 < len(s) && s[i+1] == '&':
			return i, i + 2
		case s[i] == '&':
			return i, i + 1
		case s[i] == '|' && i+1 < len(s) && s[i+1] == '|':
			return i, i + 2
		}
	}
	return len(s), len(s)
}

