// StripInstallStep removes every command that runs the Entire install helper,
// wherever it sits in the chain, along with the operator that joined it.
//
// Removal keys on InstallCLIMarker, not on the exact InstallCLIStep text, so a
// step written by an older CLI (or moved by hand) still comes out —
// MentionsEntireInstall already recognizes those, and a detect/remove pair
// that disagreed would leave `entire disable` stranding wiring it can see.
// Bytes outside the removed span are preserved exactly.
func StripInstallStep(install string) string {
	for {
		start, end, found := entireStepSpan(install)
		if !found {
			return strings.TrimSpace(install)
		}
		next := cutCommand(install, start, end)
		if next == "" {
			return ""
		}
		install = next
	}
}

// entireStepSpan locates one Entire install command. The canonical
// InstallCLIStep is matched verbatim first because it carries its own
// `|| true`, which the generic boundary scan would read as the start of a
// separate command and leave behind.
func entireStepSpan(install string) (start, end int, found bool) {
	if i := strings.Index(install, InstallCLIStep); i >= 0 {
		return i, i + len(InstallCLIStep), true
	}
	marker := strings.Index(install, InstallCLIMarker)
	if marker < 0 {
		return 0, 0, false
	}
	start, _ = commandStart(install, marker)
	end, _ = commandEnd(install, marker+len(InstallCLIMarker))
	return start, end, true
}

// cutCommand removes install[start:end] together with the shell operator that
// joined it to the rest of the chain. It returns "" when nothing else remains.
func cutCommand(install string, start, end int) string {
	cmdStart, sepStart := commandStart(install, start)
	_, sepEnd := commandEnd(install, end)
	switch {
	case cmdStart > 0:
		// Joined to something on its left: take that operator with it.
		return install[:sepStart] + install[end:]
	case sepEnd > end:
		// First in the chain: take the operator on its right instead.
		return install[sepEnd:]
	default:
		return ""
	}
}

