	mode := os.FileMode(0o644)
	if info, err := os.Stat(envPath); err == nil {
		mode = info.Mode().Perm()
	}
	if err := jsonutil.WriteFileAtomic(envPath, output, mode); err != nil {
		return fmt.Errorf("write %s: %w", EnvironmentJSONRel, err)
