func TestAppendInstallStep(t *testing.T) {
	t.Parallel()
	step := InstallCLIStep
	cases := []struct {
		name    string
		install string
		want    string
	}{
		{"empty install", "", step},
		{"plain command", "npm ci", "npm ci && " + step},
		{"dangling operator", "npm ci && ", "npm ci && " + step},
		{"dangling semicolon", "npm ci; ", "npm ci && " + step},
		// A lone trailing `&` backgrounds the preceding command. Eating it
		// would make that command blocking; joining with `&&` would be a
		// shell syntax error. Both silently break the host's install.
		{"background operator", "./devserver.sh &", "./devserver.sh & " + step},
	}
	for _, tc := range cases {
		if got := AppendInstallStep(tc.install, step); got != tc.want {
			t.Errorf("%s: AppendInstallStep(%q) = %q, want %q", tc.name, tc.install, got, tc.want)
		}
	}
}

func TestStripInstallStep(t *testing.T) {
	t.Parallel()
	step := InstallCLIStep
	// The step Entire wrote before it became cwd-independent and non-fatal.
	// Removal keys on the marker, so an environment file committed by an older
	// CLI is still cleaned up by `entire disable`.
	const legacyStep = "bash .entire/install-cli.sh"
	cases := []struct {
		name    string
		install string
		want    string
	}{
		{"sole step", step, ""},
		{"trailing step", "npm ci && " + step, "npm ci"},
		{"leading step", step + " && npm ci", "npm ci"},
		{"mid-chain step", "npm ci && " + step + " && npm run build", "npm ci && npm run build"},
		{"legacy sole step", legacyStep, ""},
		{"legacy trailing step", "npm ci && " + legacyStep, "npm ci"},
		{"legacy mid-chain step", "npm ci && " + legacyStep + " && npm run build", "npm ci && npm run build"},
		{"unrelated install", "npm ci", "npm ci"},
		{"unrelated install with pipeline", "cat deps.txt | xargs npm i", "cat deps.txt | xargs npm i"},
	}
	for _, tc := range cases {
		if got := StripInstallStep(tc.install); got != tc.want {
			t.Errorf("%s: StripInstallStep(%q) = %q, want %q", tc.name, tc.install, got, tc.want)
