// Package cloudenv wires the Entire CLI install into remote agent
// environments (Cursor Cloud Agents today; other hosts can run the same step
// from their own install or start command).
package cloudenv

import (
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

// installerURL is Entire's published installer. It installs to
// ~/.local/bin/entire and is safe to re-run, so a rebuilt environment snapshot
// costs a download rather than failing.
const installerURL = "https://entire.io/install.sh"

// installerMarker identifies an Entire install step inside a host's install
// command. Detection and removal both key on it, so the step's wording can
// change without stranding a step written by an older CLI in a committed
// environment file.
const installerMarker = "entire.io/install.sh"

// InstallCLIStep is the install-command fragment a remote environment runs so
// committed hook commands that name `entire` resolve to something.
//
// It is deliberately one self-contained command that references nothing in the
// repository. A step naming a repo-relative path would need that path to be
// committed alongside the environment file, and would resolve against whatever
// directory an earlier `cd` in the chain left behind — two ways for Entire to
// break the host's whole install command rather than merely skip itself.
const InstallCLIStep = "curl -fsSL " + installerURL + " | bash"

const maxScriptScanBytes = 1 << 20

// relativeScriptRe finds repo-relative *.sh paths in a shell command.
var relativeScriptRe = regexp.MustCompile(`(?:^|[[:space:];&|])((?:\./)?(?:[[:alnum:]._-]+/)*[[:alnum:]._-]+\.sh)`)

// MentionsEntireInstall reports whether an install command (and any repo-relative
// shell scripts it invokes) already installs the Entire CLI.
func MentionsEntireInstall(install, repoRoot string) bool {
	if commandMentionsEntire(install) {
		return true
	}
	for _, script := range referencedScripts(install) {
		path := filepath.Join(repoRoot, filepath.Clean(script))
		if !isRepoRelative(repoRoot, path) {
			continue
		}
		if commandMentionsEntire(readScriptHead(path)) {
			return true
		}
	}
	return false
}

// readScriptHead returns at most maxScriptScanBytes of path. The bound is
// applied while reading, not after: an install command can name any `.sh` file
// in the repo, and os.ReadFile would pull the whole thing into memory first.
func readScriptHead(path string) string {
	f, err := os.Open(path) //nolint:gosec // repo-relative script named by the install command
	if err != nil {
		return ""
	}
	defer f.Close()
	data, err := io.ReadAll(io.LimitReader(f, maxScriptScanBytes))
	if err != nil {
		return ""
	}
	return string(data)
}

func commandMentionsEntire(s string) bool {
	// Every marker must be an install, not a mention: a script that merely
	// probes with `command -v entire` says nothing about whether the binary
	// ends up on PATH, so treating the probe as proof would silently skip
	// wiring.
	markers := []string{
		installerMarker,
		"/usr/local/bin/entire",
	}
	for _, m := range markers {
		if strings.Contains(s, m) {
			return true
		}
	}
	return false
}

func referencedScripts(install string) []string {
	matches := relativeScriptRe.FindAllStringSubmatch(install, -1)
	if len(matches) == 0 {
		return nil
	}
	out := make([]string, 0, len(matches))
	seen := make(map[string]struct{}, len(matches))
	for _, m := range matches {
		p := strings.TrimPrefix(m[1], "./")
		if strings.Contains(p, ":") { // URLs / Windows drives
			continue
		}
		if _, ok := seen[p]; ok {
			continue
		}
		seen[p] = struct{}{}
		out = append(out, p)
	}
	return out
}

func isRepoRelative(root, path string) bool {
	rel, err := filepath.Rel(root, path)
	if err != nil {
		return false
	}
	return rel != ".." && !strings.HasPrefix(rel, ".."+string(os.PathSeparator))
}

// AppendInstallStep adds step to the end of install. Empty install becomes
// step alone.
//
// A trailing chain operator (`&&`, `;`) is dropped so the join does not
// produce `a && && b`. A trailing single `&` is left alone: it is the
// background operator, and both eating it (turning a backgrounded command
// into a blocking one) and joining onto it with `&&` (a shell syntax error)
// would silently break the host's install command.
func AppendInstallStep(install, step string) string {
	install = strings.TrimSpace(install)
	for {
		trimmed := strings.TrimRight(install, " \t")
		if cut, ok := strings.CutSuffix(trimmed, "&&"); ok {
			install = cut
			continue
		}
		if cut, ok := strings.CutSuffix(trimmed, ";"); ok {
			install = cut
			continue
		}
		install = trimmed
		break
	}
	if install == "" {
		return step
	}
	if strings.HasSuffix(install, "&") {
		// `cmd & step` is the only valid join after a background operator.
		return install + " " + step
	}
	return install + " && " + step
}

// StripInstallStep removes every command that installs the Entire CLI,
// wherever it sits in the chain, along with the operator that joined it.
//
// Removal keys on installerMarker rather than on the exact InstallCLIStep
// text, so a step written by an older CLI (or moved by hand) still comes out —
// MentionsEntireInstall already recognizes those, and a detect/remove pair
// that disagreed would leave `entire disable` stranding wiring it can see.
// Bytes outside the removed span are preserved exactly.
func StripInstallStep(install string) string {
	for {
		marker := strings.Index(install, installerMarker)
		if marker < 0 {
			return strings.TrimSpace(install)
		}
		start, _ := commandStart(install, marker)
		end, _ := commandEnd(install, marker+len(installerMarker))
		next := cutCommand(install, start, end)
		if next == "" {
			return ""
		}
		install = next
	}
}

// cutCommand removes install[start:end] together with the shell operator that
// joined it to the rest of the chain. It returns "" when nothing else remains.
func cutCommand(install string, start, end int) string {
	cmdStart, sepStart := commandStart(install, start)
	_, sepEnd := commandEnd(install, end)
	switch {
	case cmdStart > 0:
		// Joined to something on its left: take that operator with it, and
		// close the gap the removal opened.
		return joinCommands(install[:sepStart], install[end:])
	case sepEnd > end:
		// First in the chain: take the operator on its right instead.
		return install[sepEnd:]
	default:
		return ""
	}
}

func joinCommands(left, right string) string {
	left = strings.TrimRight(left, " \t")
	right = strings.TrimLeft(right, " \t")
	if left == "" || right == "" {
		return left + right
	}
	return left + " " + right
}

// commandStart returns the offset of the command containing pos and the offset
// of the shell operator that precedes it (both 0 when pos is in the first
// command of the chain).
func commandStart(s string, pos int) (cmdStart, sepStart int) {
	for i := pos - 1; i >= 0; i-- {
		switch {
		case s[i] == ';':
			return i + 1, i
		case s[i] == '&' && i > 0 && s[i-1] == '&':
			return i + 1, i - 1
		case s[i] == '&':
			return i + 1, i
		case s[i] == '|' && i > 0 && s[i-1] == '|':
			return i + 1, i - 1
		}
	}
	return 0, 0
}

// commandEnd returns the offset just past the command containing pos and the
// offset just past the operator that follows it (equal when the command ends
// the chain). A lone `|` is a pipeline, not a chain operator, so it does not
// end the command — the install step itself is `curl … | bash`.
func commandEnd(s string, pos int) (cmdEnd, sepEnd int) {
	for i := pos; i < len(s); i++ {
		switch {
		case s[i] == ';':
			return i, i + 1
		case s[i] == '&' && i+1 < len(s) && s[i+1] == '&':
			return i, i + 2
		case s[i] == '&':
			return i, i + 1
		case s[i] == '|' && i+1 < len(s) && s[i+1] == '|':
			return i, i + 2
		}
	}
	return len(s), len(s)
}

